function dispWidth(s){ var w=0; for(var i=0;i<s.length;i++){ w += (s.charCodeAt(i)>0x2E80)?2:1; } return w; }
function wordWrap(text, opts){
  opts=opts||{}; var width=opts.width!=null?opts.width:80; if(width<1)width=1;
  var out=[]; var lines=String(text||'').split(/\r?\n/);
  for(var i=0;i<lines.length;i++){
    var L=lines[i]; if(!L){ out.push(''); continue; }
    var toks=L.match(/[一-龥]|[^\s一-龥]+|\s+/g)||[];
    var cur='', curW=0;
    for(var j=0;j<toks.length;j++){
      var t=toks[j], tw=dispWidth(t);
      if(/^\s+$/.test(t)){
        if(cur==='') continue;
        if(curW+tw>width){ out.push(cur); cur=''; curW=0; }
        else { cur+=t; curW+=tw; }
        continue;
      }
      if(curW+tw>width){ if(cur!=='') out.push(cur); cur=t; curW=tw; }
      else { cur+=t; curW+=tw; }
    }
    if(cur!=='') out.push(cur);
  }
  return out.join('\n');
}

var EXPORTS={dispWidth:dispWidth,wordWrap:wordWrap};

